code_extract_route:
const body = $input.first().json.body || $input.first().json;
const priority = (body.priority || 'fast').toLowerCase();
const prompt = body.prompt || body.task || 'Hello';
const route = priority === 'quality' ? 'openai' : priority === 'local' ? 'ollama' : 'groq';
return [{ json: { priority, prompt, route, request_id: Date.now().toString() } }];

code_extract_response:
const item = $input.first().json;
const text = item.choices?.[0]?.message?.content 
  || item.message?.content
  || item.response 
  || 'no response';
return [{ json: { response: text, model_used: item.model || 'unknown', route: item.route || 'unknown' } }];
